**Custom Decision Tree:**

```python
import numpy as np

class SimpleDecisionTree:
    def __init__(self, max_depth=10, min_samples_split=2):
        self.max_depth = max_depth
        self.min_samples = min_samples_split
        self.tree = None

    def gini(self, y):
        proportions = np.bincount(y) / len(y)
        return 1 - np.sum(proportions ** 2)

    def split(self, X, y, feature, threshold):
        left_mask = X[:, feature] <= threshold
        return (
            X[left_mask], y[left_mask],
            X[~left_mask], y[~left_mask]
        )

    def best_split(self, X, y):
        best_gini = float('inf')
        best_split = None

        n_features = X.shape[1]

        for feature in range(n_features):
            thresholds = np.unique(X[:, feature])

            for threshold in thresholds:
                X_left, y_left, X_right, y_right = self.split(X, y, feature, threshold)

                if len(y_left) == 0 or len(y_right) == 0:
                    continue

                # Weighted gini
                gini_left = self.gini(y_left)
                gini_right = self.gini(y_right)
                weighted_gini = (len(y_left) * gini_left + len(y_right) * gini_right) / len(y)

                if weighted_gini < best_gini:
                    best_gini = weighted_gini
                    best_split = {'feature': feature, 'threshold': threshold}

        return best_split

    def build_tree(self, X, y, depth=0):
        n_samples, n_features = X.shape
        n_classes = len(np.unique(y))

        # Stopping criteria
        if depth >= self.max_depth or n_samples < self.min_samples or n_classes == 1:
            return {'value': np.bincount(y).argmax()}

        # Find best split
        split = self.best_split(X, y)
        if split is None:
            return {'value': np.bincount(y).argmax()}

        # Recursive split
        X_left, y_left, X_right, y_right = self.split(X, y, split['feature'], split['threshold'])

        return {
            'feature': split['feature'],
            'threshold': split['threshold'],
            'left': self.build_tree(X_left, y_left, depth + 1),
            'right': self.build_tree(X_right, y_right, depth + 1)
        }

    def fit(self, X, y):
        self.tree = self.build_tree(X, y)
        return self
